// emg_model.h: generated by code/train_model.py (threshold, trained on S01-S04). Do not edit by hand.
// Use: collect EMG_MODEL_WINDOW samples of emg_mV (the filtered signal, 1000 Hz), then
//   float f[2]; emg_features(window, EMG_MODEL_WINDOW, f); int moving = emg_model_predict(f);  // 1 = mover, 0 = reposo
#pragma once
#include <math.h>

#define EMG_MODEL_WINDOW 250   // samples = 250 ms at 1000 Hz

// RMS and waveform length (WL) of one window, the same as in Python
static inline void emg_features(const float *x, int n, float f[2]) {
  float s2 = 0.0f, wl = 0.0f;
  for (int i = 0; i < n; i++) {
    s2 += x[i] * x[i];
    if (i > 0) wl += fabsf(x[i] - x[i - 1]);
  }
  f[0] = sqrtf(s2 / n);
  f[1] = wl;
}

#define EMG_MODEL_RMS_THRESHOLD 37.2000618f

static inline int emg_model_predict(const float f[2]) {
  return f[0] > EMG_MODEL_RMS_THRESHOLD ? 1 : 0;
}
